-- Title: catalog product code reuse after soft delete RPCs
-- Kind: patch
-- Intent: catalog_product_code_reuse_after_soft_delete
-- Context: TH-02 / EPIC-02 / US-01 — ignore deleted SKU/barcode owners
-- Touches: check_duplicate_product_code, create_product, update_product_profile
-- Safety: idempotent ; medium — changes product identity duplicate policy
-- Depends on: catalog_product_code_reuse_after_soft_delete_schema.sql
-- Promoted from _drafts/catalog_product_code_reuse_after_soft_delete_rpcs.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function catalog.check_duplicate_product_code(
  p_tenant_id uuid,
  p_sku text default null,
  p_barcode text default null,
  p_exclude_product_id uuid default null
)
returns table (
  duplicate_field text,
  product_id uuid,
  product_name text,
  matched_value text
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_sku text;
  v_barcode text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.create') then
    raise exception 'permission denied: catalog.product.create';
  end if;

  v_sku := catalog._normalize_product_sku(p_sku);
  v_barcode := catalog._normalize_product_barcode(p_barcode);

  return query
  select m.duplicate_field, m.product_id, m.product_name, m.matched_value
  from (
    select
      'sku'::text as duplicate_field,
      p.id as product_id,
      p.name as product_name,
      p.sku as matched_value
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.business_status <> 'soft_deleted'::catalog.product_business_status
      and v_sku is not null
      and p.sku = v_sku
      and (p_exclude_product_id is null or p.id <> p_exclude_product_id)
    union all
    select
      'barcode'::text as duplicate_field,
      p.id as product_id,
      p.name as product_name,
      p.barcode as matched_value
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.business_status <> 'soft_deleted'::catalog.product_business_status
      and v_barcode is not null
      and p.barcode = v_barcode
      and (p_exclude_product_id is null or p.id <> p_exclude_product_id)
  ) m
  order by m.duplicate_field, m.product_name;
end;
$$;

revoke all on function catalog.check_duplicate_product_code(
  uuid, text, text, uuid
) from public, anon;
grant execute on function catalog.check_duplicate_product_code(
  uuid, text, text, uuid
) to authenticated, service_role;

create or replace function catalog.create_product(
  p_tenant_id uuid,
  p_name text,
  p_reference_id text,
  p_actor_id uuid default auth.uid(),
  p_trade_name text default null,
  p_sku text default null,
  p_barcode text default null,
  p_description text default null,
  p_note text default null,
  p_images jsonb default '[]'::jsonb,
  p_base_unit_name text default null,
  p_readiness_status text default 'incomplete',
  p_readiness_blockers jsonb default '[]'::jsonb,
  p_idempotency_key uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_product_id uuid;
  v_sku text;
  v_barcode text;
  v_reference_id text;
  v_base_unit_name text;
  v_image jsonb;
  v_readiness_status catalog.product_readiness_status;
  v_storage_key text;
  v_slot_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.create') then
    raise exception 'permission denied: catalog.product.create';
  end if;

  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'product name is required';
  end if;

  if jsonb_typeof(p_images) = 'array' and jsonb_array_length(p_images) > 8 then
    raise exception 'validation_exception: Chỉ được tải lên tối đa 8 ảnh.';
  end if;

  v_reference_id := btrim(coalesce(p_reference_id, ''));
  if length(v_reference_id) = 0 then
    raise exception 'reference id is required';
  end if;

  if p_idempotency_key is not null then
    select p.id
    into v_product_id
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.idempotency_key = p_idempotency_key;

    if v_product_id is not null then
      return v_product_id;
    end if;
  end if;

  v_sku := catalog._normalize_product_sku(p_sku);
  v_barcode := catalog._normalize_product_barcode(p_barcode);
  v_base_unit_name := nullif(btrim(coalesce(p_base_unit_name, '')), '');

  if exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.reference_id = v_reference_id
  ) then
    raise exception 'duplicate reference_id';
  end if;

  if v_sku is not null
    and exists (
      select 1
      from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.business_status <> 'soft_deleted'::catalog.product_business_status
        and p.sku = v_sku
    ) then
    raise exception 'duplicate sku';
  end if;

  if v_barcode is not null
    and exists (
      select 1
      from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.business_status <> 'soft_deleted'::catalog.product_business_status
        and p.barcode = v_barcode
    ) then
    raise exception 'duplicate barcode';
  end if;

  v_readiness_status := coalesce(
    p_readiness_status::catalog.product_readiness_status,
    'incomplete'::catalog.product_readiness_status
  );

  begin
    insert into catalog.products (
      tenant_id,
      idempotency_key,
      reference_id,
      name,
      trade_name,
      sku,
      barcode,
      description,
      note,
      business_status,
      created_by,
      updated_by
    )
    values (
      p_tenant_id,
      p_idempotency_key,
      v_reference_id,
      btrim(p_name),
      nullif(btrim(coalesce(p_trade_name, '')), ''),
      v_sku,
      v_barcode,
      nullif(btrim(coalesce(p_description, '')), ''),
      nullif(btrim(coalesce(p_note, '')), ''),
      'active',
      p_actor_id,
      p_actor_id
    )
    returning id into v_product_id;
  exception
    when unique_violation then
      if exists (
        select 1 from catalog.products p
        where p.tenant_id = p_tenant_id
          and p.reference_id = v_reference_id
      ) then
        raise exception 'duplicate reference_id';
      end if;
      if v_sku is not null
        and exists (
          select 1 from catalog.products p
          where p.tenant_id = p_tenant_id
            and p.business_status <> 'soft_deleted'::catalog.product_business_status
            and p.sku = v_sku
        ) then
        raise exception 'duplicate sku';
      end if;
      if v_barcode is not null
        and exists (
          select 1 from catalog.products p
          where p.tenant_id = p_tenant_id
            and p.business_status <> 'soft_deleted'::catalog.product_business_status
            and p.barcode = v_barcode
        ) then
        raise exception 'duplicate barcode';
      end if;
      raise;
  end;

  insert into catalog.product_base_price_profiles (
    product_id,
    tenant_id,
    mode,
    base_price_after_vat,
    base_price_before_vat,
    currency
  )
  values (v_product_id, p_tenant_id, 'manual', null, null, 'VND')
  on conflict (product_id) do nothing;

  if p_images is not null and jsonb_typeof(p_images) = 'array' then
    for v_image in select * from jsonb_array_elements(p_images)
    loop
      v_storage_key := btrim(v_image ->> 'storage_key');
      if v_storage_key is null or length(v_storage_key) = 0 then
        continue;
      end if;

      begin
        v_slot_id := catalog._consume_image_upload_slot(
          p_tenant_id,
          v_storage_key,
          p_actor_id
        );
      exception
        when others then
          continue;
      end;

      insert into catalog.product_images (
        tenant_id,
        product_id,
        storage_key,
        file_url,
        is_primary,
        sort_order,
        processing_status,
        upload_slot_id
      )
      values (
        p_tenant_id,
        v_product_id,
        v_storage_key,
        nullif(btrim(coalesce(v_image ->> 'url', '')), ''),
        coalesce((v_image ->> 'is_primary')::boolean, false),
        coalesce((v_image ->> 'sort_order')::integer, 0),
        'ready',
        v_slot_id
      );
    end loop;
  end if;

  if v_base_unit_name is not null then
    insert into catalog.product_units (
      tenant_id,
      product_id,
      unit_name,
      is_base_unit,
      conversion_rate_to_base
    )
    values (
      p_tenant_id,
      v_product_id,
      v_base_unit_name,
      true,
      1
    );
  end if;

  insert into catalog.product_readiness (
    product_id,
    tenant_id,
    status,
    blockers
  )
  values (
    v_product_id,
    p_tenant_id,
    v_readiness_status,
    coalesce(p_readiness_blockers, '[]'::jsonb)
  );

  insert into catalog.product_change_history (
    tenant_id,
    product_id,
    action,
    payload,
    actor_id
  )
  values (
    p_tenant_id,
    v_product_id,
    'CREATED',
    jsonb_build_object(
      'product_id', v_product_id,
      'reference_id', v_reference_id,
      'name', btrim(p_name),
      'sku', v_sku,
      'barcode', v_barcode
    ),
    p_actor_id
  );

  return v_product_id;
end;
$$;

revoke all on function catalog.create_product(
  uuid, text, text, uuid, text, text, text, text, text, jsonb, text, text, jsonb, uuid
) from public, anon;
grant execute on function catalog.create_product(
  uuid, text, text, uuid, text, text, text, text, text, jsonb, text, text, jsonb, uuid
) to authenticated, service_role;

create or replace function catalog.update_product_profile(
  p_tenant_id uuid,
  p_product_id uuid,
  p_name text,
  p_actor_id uuid default auth.uid(),
  p_trade_name text default null,
  p_sku text default null,
  p_barcode text default null,
  p_description text default null,
  p_note text default null,
  p_expected_version integer default null,
  p_tracking_mode text default null,
  p_expiry_required boolean default null
)
returns table (
  product_id uuid,
  name text,
  trade_name text,
  sku text,
  barcode text,
  description text,
  note text,
  business_status text,
  is_soft_deleted boolean,
  primary_image_url text,
  images jsonb,
  readiness_status text,
  readiness_blockers jsonb,
  version integer
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
#variable_conflict use_column
declare
  v_product catalog.products%rowtype;
  v_sku text;
  v_barcode text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.update') then
    raise exception 'permission denied: catalog.product.update';
  end if;

  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'validation_exception: Product name is required.';
  end if;

  select *
  into v_product
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
  for update;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product.business_status = 'soft_deleted'::catalog.product_business_status then
    raise exception 'product is soft-deleted and cannot be updated';
  end if;

  if p_expected_version is not null and p_expected_version <> v_product.version then
    raise exception 'stale_product_version: expected=% current=%',
      p_expected_version,
      v_product.version;
  end if;

  v_sku := catalog._normalize_product_sku(p_sku);
  v_barcode := catalog._normalize_product_barcode(p_barcode);

  if v_sku is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.business_status <> 'soft_deleted'::catalog.product_business_status
      and p.sku = v_sku
  ) then
    raise exception 'duplicate sku';
  end if;

  if v_barcode is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.business_status <> 'soft_deleted'::catalog.product_business_status
      and p.barcode = v_barcode
  ) then
    raise exception 'duplicate barcode';
  end if;

  update catalog.products
  set name = btrim(p_name),
      trade_name = nullif(btrim(coalesce(p_trade_name, '')), ''),
      sku = v_sku,
      barcode = v_barcode,
      description = nullif(btrim(coalesce(p_description, '')), ''),
      note = nullif(btrim(coalesce(p_note, '')), ''),
      tracking_mode = coalesce(p_tracking_mode, catalog.products.tracking_mode),
      expiry_required = coalesce(p_expiry_required, catalog.products.expiry_required),
      updated_at = now(),
      updated_by = p_actor_id,
      version = catalog.products.version + 1
  where tenant_id = p_tenant_id
    and id = p_product_id;

  perform * from catalog._refresh_product_readiness(p_tenant_id, p_product_id);

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'UPDATED_PROFILE',
    jsonb_build_object(
      'before', jsonb_build_object(
        'name', v_product.name,
        'trade_name', v_product.trade_name,
        'sku', v_product.sku,
        'barcode', v_product.barcode,
        'description', v_product.description,
        'note', v_product.note
      ),
      'after', jsonb_build_object(
        'name', btrim(p_name),
        'trade_name', nullif(btrim(coalesce(p_trade_name, '')), ''),
        'sku', v_sku,
        'barcode', v_barcode,
        'description', nullif(btrim(coalesce(p_description, '')), ''),
        'note', nullif(btrim(coalesce(p_note, '')), '')
      )
    ),
    p_actor_id
  );

  return query
  select * from catalog._product_maintenance_result_row(p_tenant_id, p_product_id);
exception
  when unique_violation then
    if v_sku is not null and exists (
      select 1 from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.id <> p_product_id
        and p.business_status <> 'soft_deleted'::catalog.product_business_status
        and p.sku = v_sku
    ) then
      raise exception 'duplicate sku';
    end if;
    if v_barcode is not null and exists (
      select 1 from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.id <> p_product_id
        and p.business_status <> 'soft_deleted'::catalog.product_business_status
        and p.barcode = v_barcode
    ) then
      raise exception 'duplicate barcode';
    end if;
    raise;
end;
$$;

revoke all on function catalog.update_product_profile(
  uuid, uuid, text, uuid, text, text, text, text, text, integer, text, boolean
) from public, anon;
grant execute on function catalog.update_product_profile(
  uuid, uuid, text, uuid, text, text, text, text, text, integer, text, boolean
) to authenticated, service_role;
